import React from "react";
import "./App.css";
import { motion } from "framer-motion";
import { FaRunning, FaUser, FaHistory, FaStar } from "react-icons/fa";

function App() {
  return (
    <div className="app-container">
      {/* NAVBAR */}
      <motion.nav
        className="navbar"
        initial={{ y: -40, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.6 }}
      >
        <div className="logo">
          <FaRunning size={28} color="#ff7b00" />
          <span>RunRunRun</span>
        </div>

        <div className="nav-links">
          <a href="#profile">Profile</a>
          <a href="#runs">My Runs</a>
          <a href="#stats">Statistics</a>
        </div>
      </motion.nav>

      {/* HERO SECTION */}
      <motion.section
        className="hero"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.3, duration: 1 }}
      >
        <h1 className="hero-title">
          Track Your Runs.  
          <span className="gradient-text">Improve Every Day.</span>
        </h1>

        <p className="hero-sub">
          A beautiful and simple runner's dashboard designed just for you.
        </p>

        <motion.button
          className="cta-btn"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.97 }}
        >
          Start Run
        </motion.button>
      </motion.section>

      {/* FEATURE CARDS */}
      <section className="card-section">
        <motion.div
          className="card"
          whileHover={{ y: -8, scale: 1.02 }}
          transition={{ duration: 0.3 }}
        >
          <FaUser size={40} className="card-icon" />
          <h3>Profile</h3>
          <p>Update your running details and personal goals.</p>
        </motion.div>

        <motion.div
          className="card"
          whileHover={{ y: -8, scale: 1.02 }}
          transition={{ duration: 0.3 }}
        >
          <FaHistory size={40} className="card-icon" />
          <h3>Run History</h3>
          <p>View, delete, and analyze all your past runs.</p>
        </motion.div>

        <motion.div
          className="card"
          whileHover={{ y: -8, scale: 1.02 }}
          transition={{ duration: 0.3 }}
        >
          <FaStar size={40} className="card-icon" />
          <h3>Performance</h3>
          <p>Track pace improvements and weekly progress.</p>
        </motion.div>
      </section>

      {/* FOOTER */}
      <footer className="footer">
        <p>RunRunRun © {new Date().getFullYear()} — Keep Running Strong 🧡</p>
      </footer>
    </div>
  );
}

export default App;
